import { Component, OnInit } from "@angular/core";
import { NavParams, ModalController } from "@ionic/angular";
import { TranslateService } from "@ngx-translate/core";
import { AlertService } from "src/app/services/tnvn/services/alert.service";
import { ApiService } from "src/app/services/tnvn/services/api.service";
import { UserSessionService } from 'src/app/services/usersession.service';
@Component({
  selector: "app-apiErrorLog",
  templateUrl: "./apiErrorLog.component.html",
  styleUrls: ["./apiErrorLog.component.scss"],
})
export class ApiErrorLogComponent implements OnInit {
  viewName: any=[];
  schoolList = [];
  reasonList: any[] = [];
  mediumList: any[] = [];
  randomQuestionList: any[] = [];
  studentDetail: any;
  attemptedPercentage:number;
  attemptedPercentageValue: number =Math.round((9 / 10) * 100);
  attemptedProgress: number=Math.round((9 / 10) * 100);
  correctedProgress: number=Math.round((7 / 10) * 100);
  percentage: number=Math.round((7 / 10) * 100);
  percentageValue: number=Math.round((7 / 10) * 100);
  selectedReason: any;  
  public languageType: any;
  public selectInstruction: any;
  public studentIdentify: any;
  public ok: any;
  public ReasonAssessing: any;
  public chooseMedium: any;
  public cancel: any;
  public submit: any;

  constructor(
    private navParams: NavParams,
    private modalController: ModalController,
    private userSessionService: UserSessionService,
    public _alerService: AlertService,
    public _apiService: ApiService,
    private _translate: TranslateService
  ) {
  }


  async ngOnInit() {
      this.viewName = JSON.parse(localStorage.getItem('Error'));
      console.log(this.viewName);
    // this.attemptedProgress = Number(this.viewName.attempted_words) / Number(this.viewName.book_total_words);
    // this.correctedProgress = Number(this.viewName.correct_words) / Number(this.viewName.book_total_words);
    // this.percentage = Number(this.viewName.correct_words) / Number(this.viewName.book_total_words);
    // this.attemptedPercentageValue = Number(this.viewName.correct_words) / Number(this.viewName.attempted_words);
    // this.percentageValue = Math.round(this.percentage*100);
    // this.attemptedPercentage = Math.round(this.attemptedPercentageValue*100);
    

    this._apiService.languageInfo.subscribe((data: any) => {
      this.languageType = data;
      this._translate.use(this.languageType);
      this._initialiseTranslation();

      switch (this.languageType) {
        case "en":
          this.reasonList = this.reasonList.filter((sr) => sr.language_id == 2);
          break;
        case "ta":
          this.reasonList = this.reasonList.filter((sr) => sr.language_id == 1);
        default:
          break;
      }
    });
  }
  _initialiseTranslation(): void {
    this._translate.get("selectInstruction").subscribe((res: string) => {
      this.selectInstruction = res;
    });
    this._translate.get("ReasonAssessing").subscribe((res: string) => {
      this.ReasonAssessing = res;
    });
    this._translate.get("studentIdentify").subscribe((res: string) => {
      this.studentIdentify = res;
    });
    this._translate.get("chooseMedium").subscribe((res: string) => {
      this.chooseMedium = res;
    });
    this._translate.get("ok").subscribe((res: string) => {
      this.ok = res;
    });
    this._translate.get("cancel").subscribe((res: string) => {
      this.cancel = res;
    });
    this._translate.get("submit").subscribe((res: string) => {
      this.submit = res;
    });
  }


  mySelectHandler(event) {}

  selectReason(reason, index) {
    this.selectedReason = reason;
  }
 
  async dismiss(data) {    
    let submittedData = data;
    if (submittedData != "Cancel" && this.viewName == "view1") {
      if (this.selectedReason != undefined) {
        let studentReason = {
          student_emisid: this.studentDetail.id,
          student_name: this.studentDetail.name,
          reason: this.selectedReason.reason,
          description: "Reason for not assessing student",
        };
        await this.modalController.dismiss(studentReason);
      } else {
        this._alerService.showAlert("Please check any one");
      }
    } else {
      await this.modalController.dismiss(submittedData);
    }
  }
}
